<script setup lang="ts">
// 将报告、证券、比较、账户和实验来源渲染为可读事实卡，数值与定性回答分开。
// 接收服务端校验过归属、授权和引用范围的来源对象。
const props=defineProps<{source:any}>()
// 以中文千分位展示数值，缺失值保留明确占位符。
const fmt=(v:any)=>v===null||v===undefined?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3})
// 将事实中的报价、采集和核验时刻统一显示为北京时间。
const date=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未提供'
// 把已知证据和交易状态映射为中文，其他字段保留原始文本。
const status=(s:string)=>({verified:'已核验',unknown:'未知',active:'正常',suspended:'停牌',delisted:'退市',incomplete:'不完整',explanation_change:'同一事实，解释变化',fact_comparison:'归档事实差异'}[s]||s||'未提供')
const fields:Record<string,string>={cash:'现金',reserved_cash:'冻结现金',available_cash:'可用现金',market_value:'持仓市值',equity:'总权益',position_pct:'仓位（%）',cash_pct:'现金占比（%）',current_drawdown_pct:'当前回撤（%）',max_drawdown_pct:'最大回撤（%）',return_pct:'区间收益（%）',round_trips:'闭合交易数',fees:'累计费用',initial_cash:'初始虚拟资金',final_equity:'期末权益',fast:'快线周期',slow:'慢线周期',train_ratio:'样本内占比',stop_loss_pct:'止损比例',total:'含费总额',gross:'成交金额',min_total:'最小数量含费金额',quantity:'数量',max_quantity:'预算内最大数量',min_quantity:'最小申报数量',price:'价格',quote_time:'报价时间',verified_at:'风险核验时间',status:'核验状态',budget:'预算计算'}
// 按类型格式化标量或数值字段，复杂计算不在客户端补造结论。
function value(v:any):string{if(v===null||v===undefined)return'未提供';if(typeof v==='number')return fmt(v);if(typeof v==='boolean')return v?'是':'否';if(typeof v==='object')return Object.entries(v).filter(([,x])=>typeof x==='number').map(([k,x])=>(fields[k]||k)+' '+fmt(x)).join('；')||'详见归档计算';return status(String(v))}
</script>
<!-- 根据来源类型展示归档事实、来源时间及差异，所有正文均通过模板插值显示。 -->
<template><div class="source-facts"><p v-if="source.filtered_instrument_id">仅展示指定证券：{{source.filtered_instrument_id}}</p><p v-if="source.omitted_items" class="research-footnote">此卡片仅展示部分记录，可指定证券继续查询。</p><p v-if="typeof source.facts==='string'">{{source.facts}}</p><template v-else-if="source.kind==='report'"><p>研究日期 {{source.facts.report_date}} · 单只预算 {{fmt(source.facts.budget_limit)}}</p><div v-if="source.facts.candidates?.length" class="table-scroll"><table class="watch-table"><thead><tr><th>候选证券</th><th>归档价格 / 数量</th><th>报价时间</th></tr></thead><tbody><tr v-for="c in source.facts.candidates" :key="c.instrument_id"><td>{{c.name||c.instrument_id}}<small>{{c.instrument_id}}</small></td><td>{{fmt(c.price)}} / {{c.quantity}}</td><td>{{date(c.quote_time)}}</td></tr></tbody></table></div><p v-if="!source.facts.candidates?.length">{{source.filtered_instrument_id?'指定证券未出现在候选记录中。':'这次归档没有合格模拟候选。'}}</p><div v-for="c in source.facts.budget_calculations" :key="c.instrument_id"><b>{{c.instrument_id}} · 程序预算</b><p>{{value(c.saved_budget)}}<span v-if="c.saved_budget.fees">；预计费用 {{value(c.saved_budget.fees)}}</span></p></div><p v-for="c in source.facts.excluded" :key="c.instrument_id"><b>{{c.name||c.instrument_id}}</b> · {{c.reasons?.join('；')}}</p><details v-if="source.facts.sources?.length"><summary>原始证据与数据时间</summary><div v-for="s in source.facts.sources" :key="s.id"><a v-if="s.url&&/^https?:\/\//i.test(s.url)" :href="s.url" target="_blank" rel="noopener noreferrer">{{s.instrument_id}} · {{s.source}}</a><small>报价 {{date(s.quote_time)}} · 采集 {{date(s.collected_at)}}</small></div></details></template>
<template v-else-if="source.kind==='preferences'"><p>当前个人研究配置，完整设置可从来源打开。</p><dl><dt>单只证券预算（元）</dt><dd>{{fmt(source.facts.budget)}}</dd><dt>最低日成交额（元）</dt><dd>{{fmt(source.facts.min_daily_amount)}}</dd><dt>风险核验有效期（小时）</dt><dd>{{source.facts.max_risk_age_hours}}</dd><dt>早报 / 收盘 / 复盘时间</dt><dd>{{source.facts.morning_time}} / {{source.facts.closing_time}} / {{source.facts.weekly_time}}</dd><dt>自动 AI</dt><dd>{{source.facts.automatic_ai?'开启':'关闭'}}</dd></dl></template>
<template v-else-if="source.kind==='watchlist'"><p>已记录持仓 {{source.facts.recorded_count||0}} 只。金额和收益按已存日K现算，不含费用。</p><p v-if="!source.facts.items?.length">尚未记录持仓价和持仓数量。</p><div v-else class="table-scroll"><table class="watch-table"><thead><tr><th>证券 / 代码</th><th>持仓价</th><th>数量</th><th>持仓金额</th><th>总收益</th></tr></thead><tbody><tr v-for="row in source.facts.items" :key="row.instrument_id"><td>{{row.official_name||row.instrument_id}}<small>{{row.instrument_id}}</small></td><td>{{fmt(row.position?.cost_price)}}</td><td>{{row.position?.quantity ?? '—'}}</td><td>{{fmt(row.position?.market_value)}}</td><td>{{fmt(row.position?.total_pnl)}}</td></tr></tbody></table></div></template>
<template v-else-if="source.kind==='instrument'"><p>{{source.title}} · {{source.facts.instrument_id}}</p><p>状态 {{status(source.facts.status)}} · 核验 {{date(source.facts.verified_at)}}</p><p v-if="source.facts.quote_quality&&source.facts.quote_quality!=='valid'" class="warning-text">{{source.facts.quote_quality==='unavailable'?'缺少报价':'报价尚不可核验'}}</p><p v-for="note in source.facts.quote_notes" :key="note">{{note}}</p><p v-for="note in source.facts.risk_notes" :key="note">{{note}}</p><p v-if="source.facts.quote">开盘 {{fmt(source.facts.quote.open)}} · 收盘 {{fmt(source.facts.quote.close)}} · {{date(source.facts.quote.ts)}}</p><p v-else>缺少有效报价资料。</p><p v-if="source.facts.position">持仓价 {{fmt(source.facts.position.cost_price)}} · 数量 {{source.facts.position.quantity ?? '—'}} · 持仓金额 {{fmt(source.facts.position.market_value)}} · 总收益 {{fmt(source.facts.position.total_pnl)}}</p></template>
<template v-else-if="source.kind==='comparison'"><p>{{status(source.facts.kind)}}</p><p v-if="source.facts.missing_original_facts">部分报告缺少原始事实，不以当前资料补写历史差异。</p><p>新增候选：{{source.facts.added.join('、')||'无'}}；移出候选：{{source.facts.removed.join('、')||'无'}}</p><div v-for="c in source.facts.changed" :key="c.instrument_id"><b>{{c.instrument_id}}</b><p v-for="(pair,k) in c.fields" :key="k">{{fields[k]||k}} · 左侧 {{value(pair.left)}} → 右侧 {{value(pair.right)}}</p></div><p v-for="c in source.facts.excluded_changes" :key="c.instrument_id">{{c.instrument_id}} · 左侧 {{c.left?.join('；')||'未排除'}} → 右侧 {{c.right?.join('；')||'未排除'}}</p></template>
<template v-else-if="source.kind==='account'"><dl><template v-for="(v,k) in source.facts" :key="k"><template v-if="fields[k]"><dt>{{fields[k]}}</dt><dd>{{value(v)}}</dd></template></template></dl><p v-for="g in source.facts.gaps" :key="g.instrument_id">{{g.instrument_id}} · {{g.reasons.join('；')}}</p><div v-if="source.facts.fills" class="table-scroll"><table class="watch-table"><thead><tr><th>已授权模拟成交</th><th>方向 / 数量</th><th>价格 / 费用</th></tr></thead><tbody><tr v-for="(f,i) in source.facts.fills" :key="i"><td>{{f.instrument_id}}<small>{{date(f.filled_at)}}</small></td><td>{{f.side==='buy'?'买':'卖'}} {{f.quantity}}</td><td>{{fmt(f.fill_price)}} / {{fmt(f.fees)}}</td></tr></tbody></table></div></template>
<template v-else><p v-if="source.facts.validated!==undefined">历史证据：{{source.facts.validated?'已核验':'未验证或无结果'}}</p><dl><template v-for="(v,k) in {...source.facts.parameters,...source.facts.summary}" :key="k"><template v-if="fields[k]"><dt>{{fields[k]}}</dt><dd>{{value(v)}}</dd></template></template></dl><p v-for="w in source.facts.warnings" :key="w">{{w}}</p></template></div></template>
<style scoped>/* 事实卡使用紧凑标签与可换行正文，表格保留横向滚动以容纳证据时间。 */
.source-facts{padding:10px 0;font-size:11px;line-height:1.9;overflow-wrap:anywhere}.source-facts p{margin:7px 0}.source-facts b{font-weight:550;color:#536e59}.source-facts small{display:block;color:#94a095;font-size:10px}.source-facts dl{display:grid;grid-template-columns:minmax(100px,1fr) minmax(0,1fr);gap:8px;margin:10px 0}.source-facts dt{color:#84968a}.source-facts dd{margin:0}.source-facts a{color:#488763}.source-facts .watch-table{font-size:11px}.source-facts details{margin-top:12px}</style>
